function maxHeapify(i, heapSize) {
  while (true) {
    mark(i, "current");
    let l = left(i);
    let r = right(i);
    let largest = i;

    if (l <= heapSize && greater(l, largest)) {
      largest = l;
    }
    if (r <= heapSize && greater(r, largest)) {
      largest = r;
    }

    if (largest !== i) {
      mark(largest, "largest");
      swap(i, largest);
      i = largest;
    } else {
      break;
    }
  }
}

